/**
 * FF360 Gym QR — Cloudflare Worker, v2
 * ---------------------------------------------------------------------------
 * Paste this whole file into the Worker editor, replacing everything, Deploy.
 *
 * It does two jobs:
 *   /       serves the page
 *   /api    passes the page's calls on to Apps Script and returns the answer
 *
 * The /api hop is the point. A reply from Apps Script is redirected to
 * googleusercontent.com, and a fair number of phones and networks refuse to
 * follow that from inside a page — which looks exactly like the server being
 * down, even though the row was written. Fetching it here instead means the
 * browser only ever talks to this domain.
 *
 * The shared key lives here now, not in the page.
 * ---------------------------------------------------------------------------
 */

const SCRIPT_URL = "https://script.google.com/macros/s/AKfycbzIHmNVLEPGATbXxI-lwO-AWmAeeI68OANOFTBSSU9FFn-AMXmW3xsxr6Fk7Q5_CqOl/exec";
const SHARED_KEY = "FF360@2017";

const PAGE = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Fitness Fuel 360 \u2014 Gym Offer</title>\n\n<script>\n/* ==========================================================================\n   FF360 Gym QR \u2014 v1  (standalone, to be merged into FF360 One later)\n\n   Two screens live in this one file:\n     \u2022 the public form   \u2014 what the gym QR opens (default view)\n     \u2022 verification      \u2014 open this file with ?staff=1\n\n   The verification screen is TEMPORARY. It exists so the flow can be tested\n   end to end before the tab is built inside FF360 One, where sign-in and the\n   role rules already handle who may see it. Do not hand this URL to stores.\n\n   SET THESE TWO LINES after deploying the Apps Script on the new workbook.\n   ========================================================================== */\nvar FF_GYM_URL = \"https://script.google.com/macros/s/AKfycbzIHmNVLEPGATbXxI-lwO-AWmAeeI68OANOFTBSSU9FFn-AMXmW3xsxr6Fk7Q5_CqOl/exec\";\nvar FF_GYM_KEY = \"FF360@2017\";    /* must match SHARED_KEY in the script  */\n\n/* The logo, once you have it: a URL, or paste the whole file in as a data URI\n   so the page still shows it with no connection. Left empty, both the opening\n   screen and the header fall back to the plain FF mark. */\nvar FF_LOGO = \"data:image/png;base64,\";\n</script>\n\n<style>\n:root{\n  --plane:#f4f2ed; --surface-1:#fff; --surface-2:#faf8f4; --sand:#efeade;\n  --ink:#14120e; --ink-2:#55514a; --muted:#8b867b;\n  --grid:#ece9e1; --line:#d6d1c5; --border:rgba(20,18,14,.11);\n  --brand:#1f1d18; --brand-hover:#332f27; --brand-deep:#7d5717;\n  --accent:#a8761f; --accent-soft:#f6ecd8; --gold:#d9a44a;\n  --good-text:#136b39; --good-soft:#e2f2e8;\n  --warn-text:#8a6209; --warn-soft:#faf0d6;\n  --crit-text:#9c2c20; --crit-soft:#fbe8e5;\n  --r-sm:8px; --r:12px; --r-lg:16px;\n  --shadow-sm:0 1px 2px rgba(20,18,14,.05);\n  --shadow:0 1px 2px rgba(20,18,14,.05),0 6px 16px -6px rgba(20,18,14,.10);\n  --t:150ms cubic-bezier(.2,.6,.3,1);\n}\n*{box-sizing:border-box}\nhtml{color-scheme:light}\nbody{margin:0;background:var(--plane);color:var(--ink);line-height:1.5;\n  font-family:ui-sans-serif,-apple-system,BlinkMacSystemFont,\"Segoe UI\",system-ui,sans-serif;\n  -webkit-font-smoothing:antialiased}\n\n/* ---------- the band at the top: the sign-in screen's dark + gold --------- */\n.hero{position:relative;overflow:hidden;background:#16150f;color:#f7f5f1;\n  padding:30px 22px 34px;text-align:center}\n.hero::after{content:\"\";position:absolute;left:0;right:0;bottom:0;height:3px;\n  background:linear-gradient(90deg,#7d5717,#c9a86a,#a8761f)}\n.hero .bloom{position:absolute;border-radius:50%;filter:blur(80px);opacity:.5;pointer-events:none}\n.hero .bloom.a{width:340px;height:340px;left:-110px;top:-150px;\n  background:radial-gradient(circle,rgba(168,118,31,.6),transparent 68%)}\n.hero .bloom.b{width:300px;height:300px;right:-110px;bottom:-170px;\n  background:radial-gradient(circle,rgba(201,168,106,.45),transparent 68%)}\n.hero-in{position:relative;max-width:520px;margin:0 auto}\n.mark{width:52px;height:52px;border-radius:50%;background:#14120e;margin:0 auto 14px;\n  display:flex;align-items:center;justify-content:center;font-weight:700;font-size:15px;\n  letter-spacing:.5px;color:var(--gold);box-shadow:0 0 0 2px rgba(201,168,106,.35)}\n.hero h1{margin:0;font-size:24px;font-weight:700;letter-spacing:-.7px}\n.hero p{margin:8px 0 0;font-size:13.5px;color:#b9b4a8;line-height:1.7}\n.hero .gymline{margin-top:14px;display:inline-block;border-radius:999px;padding:5px 15px;\n  font-size:12px;font-weight:650;background:rgba(217,164,74,.14);color:var(--gold);\n  border:1px solid rgba(217,164,74,.3)}\n\n/* ---------- shell -------------------------------------------------------- */\n.wrap{max-width:520px;margin:0 auto;padding:22px 18px 64px}\n.wrap.wide{max-width:820px}\n.card{background:var(--surface-1);border:1px solid var(--border);border-radius:var(--r-lg);\n  box-shadow:var(--shadow);padding:22px;margin-bottom:16px}\n.card h2{margin:0 0 4px;font-size:16px;font-weight:650;letter-spacing:-.35px}\n.card .note{margin:0 0 18px;font-size:12.5px;color:var(--muted);line-height:1.6}\n\n/* ---------- fields ------------------------------------------------------- */\n.f{margin-bottom:15px}\n.f label{display:block;font-size:12px;font-weight:650;color:var(--ink-2);margin-bottom:6px}\n.f label .req{color:var(--accent)}\n.f input,.f select{width:100%;padding:11px 13px;border:1px solid var(--border);\n  border-radius:var(--r-sm);font-size:15px;font-family:inherit;color:var(--ink);\n  background:var(--surface-2);transition:border-color var(--t),box-shadow var(--t),background var(--t)}\n.f input::placeholder{color:var(--muted)}\n.f input:hover,.f select:hover{border-color:var(--line)}\n.f input:focus,.f select:focus{outline:none;border-color:var(--accent);background:var(--surface-1);\n  box-shadow:0 0 0 3px var(--accent-soft)}\n.f input[readonly]{background:var(--sand);color:var(--ink-2)}\n.f .hint{font-size:11.5px;color:var(--muted);margin-top:5px}\n.f.bad input,.f.bad select{border-color:var(--crit-text);box-shadow:0 0 0 3px var(--crit-soft)}\n.f .err{font-size:11.5px;color:var(--crit-text);margin-top:5px;display:none}\n.f.bad .err{display:block}\n.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n@media(max-width:420px){.two{grid-template-columns:1fr}}\n\n/* ---------- buttons ------------------------------------------------------ */\n.btn{width:100%;background:var(--brand);color:var(--surface-1);border:1px solid var(--brand);\n  border-radius:var(--r-sm);padding:13px 18px;font-size:15px;font-weight:650;font-family:inherit;\n  cursor:pointer;box-shadow:var(--shadow-sm);transition:background var(--t),border-color var(--t)}\n.btn:hover:not(:disabled){background:var(--brand-hover);border-color:var(--brand-hover)}\n.btn:disabled{opacity:.6;cursor:default}\n.btn.gold{background:linear-gradient(145deg,#c9a86a 0%,#a8761f 55%,#7d5717 100%);\n  border-color:#a8761f;color:#1b1710;box-shadow:0 2px 10px -4px rgba(168,118,31,.75)}\n.btn.gold:hover:not(:disabled){background:linear-gradient(145deg,#dbb56a 0%,#a8761f 55%,#6d4b14 100%);\n  border-color:var(--gold)}\n.btn-sec{background:var(--surface-1);color:var(--ink-2);border:1px solid var(--border);\n  border-radius:var(--r-sm);padding:10px 16px;font-size:13px;font-weight:600;font-family:inherit;\n  cursor:pointer;transition:border-color var(--t),color var(--t),background var(--t)}\n.btn-sec:hover{border-color:var(--line);color:var(--ink);background:var(--surface-2)}\n.btn:focus-visible,.btn-sec:focus-visible,.choice:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n.inline{width:auto}\n\n/* ---------- the two choices --------------------------------------------- */\n.choice{display:flex;align-items:center;gap:14px;width:100%;text-align:left;\n  background:var(--surface-1);border:1px solid var(--border);border-radius:var(--r);\n  padding:16px 18px;margin-bottom:12px;cursor:pointer;font-family:inherit;\n  transition:border-color var(--t),background var(--t),transform var(--t)}\n.choice:hover{border-color:var(--accent);background:var(--surface-2)}\n.choice:active{transform:scale(.995)}\n.choice .ic{width:40px;height:40px;border-radius:11px;flex:none;display:flex;\n  align-items:center;justify-content:center;font-size:19px;\n  background:var(--accent-soft);color:var(--brand-deep)}\n.choice .t{font-size:15px;font-weight:650;letter-spacing:-.2px;color:var(--ink)}\n.choice .s{font-size:12.5px;color:var(--muted);margin-top:2px;line-height:1.5}\n.choice:disabled{opacity:.55;cursor:default}\n.choice:disabled:hover{border-color:var(--border);background:var(--surface-1)}\n\n/* ---------- the code ----------------------------------------------------- */\n.codebox{border:1px dashed rgba(168,118,31,.55);background:#fdf8ee;border-radius:var(--r);\n  padding:22px 18px;text-align:center;margin-bottom:16px}\n.codebox .k{font-size:11.5px;font-weight:650;color:var(--brand-deep);margin-bottom:9px}\n.codebox .v{font-family:ui-monospace,SFMono-Regular,Consolas,Menlo,monospace;\n  font-size:29px;font-weight:700;letter-spacing:2px;color:var(--ink);word-break:break-all}\n.codebox .exp{font-size:12.5px;color:var(--muted);margin-top:9px}\n.terms{border-top:1px solid var(--grid);padding-top:14px;font-size:12.5px;color:var(--ink-2);line-height:1.85}\n.terms b{color:var(--ink)}\n\n/* ---------- tags, banners ------------------------------------------------ */\n.tag{display:inline-block;border-radius:999px;padding:3px 11px;font-size:11px;font-weight:700;\n  letter-spacing:.2px}\n.tag.green{background:var(--good-soft);color:var(--good-text)}\n.tag.amber{background:var(--warn-soft);color:var(--warn-text)}\n.tag.red{background:var(--crit-soft);color:var(--crit-text)}\n.tag.grey{background:var(--surface-2);color:var(--muted);border:1px solid var(--border)}\n.banner{border-radius:var(--r-sm);padding:11px 14px;font-size:12.5px;line-height:1.6;margin-bottom:16px}\n.banner.warn{background:var(--warn-soft);color:var(--warn-text)}\n.banner.bad{background:var(--crit-soft);color:var(--crit-text)}\n.banner.ok{background:var(--good-soft);color:var(--good-text)}\n\n/* ---------- verification ------------------------------------------------- */\n.staffbar{background:var(--surface-1);border-bottom:1px solid var(--border);padding:13px 22px;\n  display:flex;align-items:center;gap:12px;flex-wrap:wrap}\n.staffbar .b{font-weight:650;font-size:15px;letter-spacing:-.3px}\n.staffbar .b small{display:block;font-size:11.5px;color:var(--muted);font-weight:500}\n.staffbar .sp{flex:1}\n.srow{display:flex;gap:10px;flex-wrap:wrap}\n.srow input{flex:1 1 240px;min-width:0;padding:11px 13px;border:1px solid var(--border);\n  border-radius:var(--r-sm);font-size:14px;font-family:inherit;background:var(--surface-2);color:var(--ink)}\n.srow input:focus{outline:none;border-color:var(--accent);background:var(--surface-1);\n  box-shadow:0 0 0 3px var(--accent-soft)}\n.dl{display:grid;grid-template-columns:132px 1fr;gap:9px 16px;font-size:13.5px;margin:0}\n.dl dt{color:var(--muted);font-size:12px;font-weight:600}\n.dl dd{margin:0;color:var(--ink)}\n@media(max-width:460px){.dl{grid-template-columns:1fr;gap:2px 0}.dl dd{margin-bottom:9px}}\n.vhead{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;\n  padding-bottom:15px;margin-bottom:15px;border-bottom:1px solid var(--grid)}\n.vhead .c{font-family:ui-monospace,SFMono-Regular,Consolas,Menlo,monospace;font-size:20px;\n  font-weight:700;letter-spacing:1px}\n\n/* ---------- the opening -------------------------------------------------\n   A QR is scanned standing up, phone in hand, so this gets one and a half\n   seconds and not a moment more. The mark lands, a light crosses it, the name\n   settles, then the whole panel lifts and the form is already behind it \u2014\n   it should read as the screen opening, not as a splash you sit through.\n   A tap skips it, and it does not run at all for anyone whose phone asks for\n   less motion.\n   ---------------------------------------------------------------------- */\nbody.ff-intro{overflow:hidden}\n#intro{position:fixed;inset:0;z-index:300;background:#16150f;overflow:hidden;\n  display:flex;align-items:center;justify-content:center;padding:24px;\n  transition:transform .5s cubic-bezier(.65,0,.35,1),opacity .5s ease}\n#intro.is-leaving{transform:translateY(-8%);opacity:0}\n#intro[hidden]{display:none!important}\n#intro .bloom{position:absolute;border-radius:50%;filter:blur(80px);opacity:0;\n  animation:in-bloom .9s ease forwards}\n#intro .bloom.a{width:360px;height:360px;left:-120px;top:-150px;\n  background:radial-gradient(circle,rgba(168,118,31,.65),transparent 68%)}\n#intro .bloom.b{width:320px;height:320px;right:-120px;bottom:-160px;\n  background:radial-gradient(circle,rgba(201,168,106,.5),transparent 68%);\n  animation-delay:.12s}\n@keyframes in-bloom{to{opacity:.55}}\n\n.intro-in{position:relative;text-align:center}\n.intro-mark{position:relative;width:88px;height:88px;border-radius:50%;margin:0 auto;\n  background:#14120e;overflow:hidden;display:flex;align-items:center;justify-content:center;\n  font-size:25px;font-weight:700;letter-spacing:1px;color:var(--gold);\n  box-shadow:0 0 0 2px rgba(201,168,106,.35),0 18px 40px -18px rgba(0,0,0,.9);\n  opacity:0;transform:scale(.82);animation:in-mark .5s cubic-bezier(.2,.75,.3,1) forwards}\n.intro-mark img{width:100%;height:100%;object-fit:cover;display:block}\n@keyframes in-mark{to{opacity:1;transform:scale(1)}}\n\n/* the light that crosses the mark once it has landed */\n.intro-mark::after{content:\"\";position:absolute;top:-30%;left:-140%;width:60%;height:160%;\n  transform:rotate(18deg);\n  background:linear-gradient(100deg,transparent,rgba(240,214,150,.75),transparent);\n  animation:in-sweep .75s cubic-bezier(.4,0,.3,1) .32s both}\n@keyframes in-sweep{to{left:150%}}\n\n.intro-word{margin-top:18px;font-size:17px;font-weight:650;letter-spacing:-.3px;color:#f7f5f1;\n  opacity:0;transform:translateY(8px);animation:in-word .5s ease .42s forwards}\n.intro-sub{margin-top:5px;font-size:12px;color:#8e887c;opacity:0;\n  animation:in-word .5s ease .58s forwards}\n@keyframes in-word{to{opacity:1;transform:none}}\n\n@media(prefers-reduced-motion:reduce){\n  #intro,.intro-mark,.intro-word,.intro-sub,#intro .bloom{\n    animation:none!important;transition:none!important;opacity:1;transform:none}\n  .intro-mark::after{display:none}\n}\n\n.foot{text-align:center;font-size:11.5px;color:var(--muted);padding:6px 18px 0;line-height:1.7}\n[hidden]{display:none!important}\n.spin{display:inline-block;width:13px;height:13px;border:2px solid currentColor;\n  border-right-color:transparent;border-radius:50%;vertical-align:-2px;margin-right:7px;\n  animation:sp .7s linear infinite}\n@keyframes sp{to{transform:rotate(360deg)}}\n@media(prefers-reduced-motion:reduce){*{animation-duration:.01ms!important;transition-duration:.01ms!important}}\n</style>\n</head>\n<body>\n\n\n<!-- ====================== the opening ================================= -->\n<div id=\"intro\" aria-hidden=\"true\">\n  <span class=\"bloom a\"></span><span class=\"bloom b\"></span>\n  <div class=\"intro-in\">\n    <div class=\"intro-mark\" id=\"introMark\">FF</div>\n    <div class=\"intro-word\">Fitness Fuel 360</div>\n    <div class=\"intro-sub\">Gym member offer</div>\n  </div>\n</div>\n\n<!-- ====================== PUBLIC: the QR form ========================== -->\n<div id=\"pub\">\n  <div class=\"hero\">\n    <span class=\"bloom a\"></span><span class=\"bloom b\"></span>\n    <div class=\"hero-in\">\n      <div class=\"mark\">FF</div>\n      <h1>Fitness Fuel 360</h1>\n      <p id=\"heroSub\">Fill in your details to claim your gym member offer.</p>\n      <span class=\"gymline\" id=\"gymTag\" hidden></span>\n    </div>\n  </div>\n\n  <div class=\"wrap\">\n\n    <div class=\"banner bad\" id=\"msg\" hidden></div>\n\n    <!-- step 1 -->\n    <div class=\"card\" id=\"stepForm\">\n      <div class=\"banner warn\" id=\"setupWarn\" hidden>\n        This page is not connected yet. Paste the Apps Script URL into\n        <b>FF_GYM_URL</b> at the top of the file.\n      </div>\n      <h2>Your details</h2>\n      <p class=\"note\">We use this only to issue your offer and keep your record at the store.</p>\n\n      <div class=\"f\" id=\"f-name\">\n        <label for=\"i-name\">Full name <span class=\"req\">*</span></label>\n        <input id=\"i-name\" type=\"text\" autocomplete=\"name\" placeholder=\"Your name\">\n        <div class=\"err\">Enter your name.</div>\n      </div>\n\n      <div class=\"f\" id=\"f-mobile\">\n        <label for=\"i-mobile\">Mobile number <span class=\"req\">*</span></label>\n        <input id=\"i-mobile\" type=\"tel\" inputmode=\"numeric\" maxlength=\"10\" autocomplete=\"tel\" placeholder=\"10 digits\">\n        <div class=\"hint\">Your code is linked to this number.</div>\n        <div class=\"err\">Enter a valid 10-digit mobile number.</div>\n      </div>\n\n      <div class=\"f\" id=\"f-email\">\n        <label for=\"i-email\">Email <span class=\"req\">*</span></label>\n        <input id=\"i-email\" type=\"email\" autocomplete=\"email\" placeholder=\"you@example.com\">\n        <div class=\"err\">Enter a valid email address.</div>\n      </div>\n\n      <div class=\"two\">\n        <div class=\"f\" id=\"f-gender\">\n          <label for=\"i-gender\">Gender <span class=\"req\">*</span></label>\n          <select id=\"i-gender\">\n            <option value=\"\">Select</option>\n            <option>Male</option><option>Female</option><option>Other</option>\n          </select>\n          <div class=\"err\">Select one.</div>\n        </div>\n        <div class=\"f\" id=\"f-dob\">\n          <label for=\"i-dob\">Date of birth <span class=\"req\">*</span></label>\n          <input id=\"i-dob\" type=\"date\">\n          <div class=\"hint\" id=\"ageHint\"></div>\n          <div class=\"err\">Enter a valid date of birth.</div>\n        </div>\n      </div>\n\n      <div class=\"f\" id=\"f-gym\">\n        <label for=\"i-gym\">Gym name <span class=\"req\">*</span></label>\n        <input id=\"i-gym\" type=\"text\" placeholder=\"The gym where you saw this code\">\n        <div class=\"err\">Enter your gym name.</div>\n      </div>\n\n      <button class=\"btn\" id=\"btnNext\">Continue</button>\n    </div>\n\n    <!-- step 2 -->\n    <div class=\"card\" id=\"stepChoice\" hidden>\n      <h2>What would you like?</h2>\n      <p class=\"note\" id=\"choiceNote\">Pick one. You can come back for the other later.</p>\n\n      <button class=\"choice\" id=\"cRedeem\">\n        <span class=\"ic\">%</span>\n        <span>\n          <span class=\"t\">Get my discount code</span>\n          <span class=\"s\">10% off at Fitness Fuel 360, valid for 90 days</span>\n        </span>\n      </button>\n\n      <button class=\"choice\" id=\"cHealth\">\n        <span class=\"ic\">\u2665</span>\n        <span>\n          <span class=\"t\">Health guidance</span>\n          <span class=\"s\">A few questions, then supplement and nutrition advice</span>\n        </span>\n      </button>\n\n      <button class=\"btn-sec inline\" id=\"backToForm\" style=\"margin-top:6px\">Back</button>\n    </div>\n\n    <!-- step 3a -->\n    <div class=\"card\" id=\"stepCode\" hidden>\n      <div class=\"banner ok\" id=\"oldCodeNote\" hidden>\n        You already have a code on this number, so here it is again.\n      </div>\n      <h2 id=\"codeTitle\">Your discount code</h2>\n      <p class=\"note\">Show this at any Fitness Fuel 360 store to get your discount.</p>\n\n      <div class=\"codebox\">\n        <div class=\"k\">Your code</div>\n        <div class=\"v\" id=\"outCode\">\u2014</div>\n        <div class=\"exp\" id=\"outExp\"></div>\n      </div>\n\n      <button class=\"btn-sec inline\" id=\"btnCopy\" style=\"margin-bottom:16px\">Copy code</button>\n\n      <div class=\"terms\">\n        <b>10% off</b> on all products at Fitness Fuel 360.<br>\n        One-time use \u2014 the code stops working once it is used.<br>\n        Valid till <b id=\"outExp2\">\u2014</b>, one code per mobile number.\n      </div>\n    </div>\n\n    <!-- step 3b -->\n    <div class=\"card\" id=\"stepHealth\" hidden>\n      <h2>Health guidance</h2>\n      <p class=\"note\">\n        Your details are saved. The guidance questions are being finalised and will\n        open here shortly \u2014 the store team can help you in the meantime.\n      </p>\n      <button class=\"btn-sec inline\" id=\"backToChoice\">Back</button>\n    </div>\n\n    <div class=\"foot\">Fitness Fuel 360 \u00b7 offer applies in store only</div>\n  </div>\n</div>\n\n<!-- ====================== check screen (?debug=1) ====================== -->\n<div id=\"dbg\" hidden>\n  <div class=\"staffbar\"><div class=\"b\">Connection check <small>Run this on the phone that fails</small></div></div>\n  <div class=\"wrap wide\">\n    <div class=\"card\">\n      <p class=\"note\" style=\"margin-bottom:14px\">\n        This sends the same ping you typed into the address bar, but from inside the page.\n        If it answers here, the phone is fine and the fault is in what the form sends.\n        If it says BLOCKED, this phone is stopping the page from calling out \u2014\n        a content blocker, Lockdown Mode, or a private-browsing setting.\n      </p>\n      <button class=\"btn\" id=\"dbgPing\">Run the check</button>\n      <pre id=\"dbgLog\" style=\"white-space:pre-wrap;word-break:break-all;font-size:12px;\n        background:var(--surface-2);border:1px solid var(--border);border-radius:8px;\n        padding:12px;margin:16px 0 0;min-height:80px;color:var(--ink-2)\"></pre>\n    </div>\n  </div>\n</div>\n\n<!-- ====================== STAFF: verification ========================== -->\n<div id=\"staff\" hidden>\n  <div class=\"staffbar\">\n    <div class=\"b\">Code check <small>Gym offer verification</small></div>\n    <div class=\"sp\"></div>\n    <span class=\"tag amber\">Test screen \u2014 moves into FF360 One</span>\n  </div>\n\n  <div class=\"wrap wide\">\n    <div class=\"banner bad\" id=\"msgS\" hidden></div>\n    <div class=\"card\">\n      <h2>Find a code</h2>\n      <p class=\"note\">Type the code the customer shows, or their mobile number.</p>\n      <div class=\"srow\">\n        <input id=\"q\" type=\"text\" placeholder=\"FF360-8K2X9A or 9876543210\" autocomplete=\"off\">\n        <button class=\"btn inline\" id=\"btnFind\" style=\"width:auto;padding:11px 22px\">Search</button>\n      </div>\n      <div class=\"f\" style=\"margin:15px 0 0\">\n        <label for=\"i-store\">Marking as used at</label>\n        <input id=\"i-store\" type=\"text\" placeholder=\"Store name and your name\">\n        <div class=\"hint\">Saved with the code so you know who applied it. In FF360 One this comes from the signed-in user.</div>\n      </div>\n    </div>\n\n    <div class=\"card\" id=\"vResult\" hidden></div>\n  </div>\n</div>\n\n<script>\n\"use strict\";\n\n/* ---------- helpers ------------------------------------------------------ */\nvar $  = function(id){ return document.getElementById(id); };\nvar esc = function(s){ return String(s==null?\"\":s).replace(/[&<>\"']/g,function(c){\n  return {\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]; }); };\n\nfunction qs(k){\n  var m = new RegExp(\"[?&]\"+k+\"=([^&#]*)\").exec(location.search);\n  return m ? decodeURIComponent(m[1].replace(/\\+/g,\" \")) : \"\";\n}\nfunction niceDate(iso){\n  if(!iso) return \"\u2014\";\n  var p = /^(\\d{4})-(\\d{2})-(\\d{2})/.exec(String(iso));\n  if(!p) return String(iso);\n  var M = [\"Jan\",\"Feb\",\"Mar\",\"Apr\",\"May\",\"Jun\",\"Jul\",\"Aug\",\"Sep\",\"Oct\",\"Nov\",\"Dec\"];\n  return Number(p[3]) + \" \" + M[Number(p[2])-1] + \" \" + p[1];\n}\nfunction ageFrom(iso){\n  var p = /^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(String(iso||\"\"));\n  if(!p) return null;\n  var b = new Date(+p[1], +p[2]-1, +p[3]), n = new Date();\n  if(isNaN(b.getTime()) || b > n) return null;\n  var a = n.getFullYear() - b.getFullYear();\n  var m = n.getMonth() - b.getMonth();\n  if(m < 0 || (m === 0 && n.getDate() < b.getDate())) a--;\n  return (a >= 0 && a < 120) ? a : null;\n}\n\n/* ---------- talking to the script ----------------------------------------\n   Hosted, the page calls its own address: /api. The Worker passes that on to\n   Apps Script from the server side and hands back the answer.\n\n   This is the third transport we have tried and the reason for it is worth\n   recording. A reply from Apps Script does not come from where you asked; the\n   request is redirected to googleusercontent.com and answered from there.\n   Plenty of phones will not follow that from inside a page \u2014 content\n   blockers, Lockdown Mode, some office and mobile networks \u2014 and the failure\n   looks identical to the server being down, even while the row is written and\n   the run shows as Completed in the log. Two phones on the same page behaved\n   differently for exactly this reason.\n\n   Going through the Worker, the browser only ever talks to our own domain.\n   There is nothing left to block. It also keeps the shared key out of the\n   page \u2014 the Worker adds it.\n\n   Opened straight from disk there is no Worker, so the old script-tag route\n   stays for local testing only.\n   ------------------------------------------------------------------------ */\nvar LOCAL = (location.protocol === \"file:\");\n\nvar LOG = [];\nfunction log_(t){\n  LOG.push(new Date().toLocaleTimeString() + \"  \" + t);\n  var box = document.getElementById(\"dbgLog\");\n  if(box) box.textContent = LOG.join(\"\\n\");\n}\n\nfunction query_(action, params){\n  var q = \"action=\" + encodeURIComponent(action);\n  for(var k in params){ if(params[k] != null && params[k] !== \"\")\n    q += \"&\" + k + \"=\" + encodeURIComponent(params[k]); }\n  return q;\n}\n\n/* hosted */\nfunction viaWorker_(action, params){\n  return fetch(\"/api?\" + query_(action, params), { cache: \"no-store\" })\n    .then(function(r){ return r.text(); })\n    .then(function(t){\n      try{ return JSON.parse(t); }\n      catch(e){ throw new Error(\"Worker replied with \" + t.slice(0, 60)); }\n    });\n}\n\n/* local file only */\nvar _cbN = 0;\nfunction viaTag_(action, params){\n  return new Promise(function(resolve, reject){\n    var cb = \"ffcb\" + (++_cbN) + \"_\" + Date.now();\n    var s  = document.createElement(\"script\");\n    var timer = setTimeout(function(){\n      log_(\"TIMED OUT: \" + action); done(); reject(new Error(\"Timed out\"));\n    }, 25000);\n    function done(){\n      clearTimeout(timer);\n      try{ delete window[cb]; }catch(e){ window[cb] = undefined; }\n      if(s.parentNode) s.parentNode.removeChild(s);\n    }\n    window[cb] = function(res){ done(); resolve(res); };\n    s.onerror = function(){ done(); reject(new Error(\"No answer from the script\")); };\n    s.src = FF_GYM_URL + \"?\" + query_(action, params)\n          + \"&key=\" + encodeURIComponent(FF_GYM_KEY) + \"&callback=\" + cb;\n    document.head.appendChild(s);\n  });\n}\n\nfunction once_(action, params){\n  log_(\"calling: \" + action);\n  var p = LOCAL ? viaTag_(action, params) : viaWorker_(action, params);\n  return p.then(function(res){\n    log_(\"answered: \" + JSON.stringify(res).slice(0, 120));\n    return res;\n  }, function(err){\n    log_(\"FAILED: \" + (err && err.message));\n    throw err;\n  });\n}\n\n/** One retry \u2014 a gym wifi drops a request now and then. Safe to repeat: the\n    script keys on the mobile number, so a call that already landed returns\n    the same code instead of making a second one. */\nfunction call(action, params){\n  return once_(action, params).catch(function(){\n    return new Promise(function(r){ setTimeout(r, 900); })\n      .then(function(){ return once_(action, params); });\n  });\n}\n\nfunction busy(btn, on, label){\n  if(on){ btn.dataset.was = btn.innerHTML; btn.disabled = true;\n          btn.innerHTML = '<span class=\"spin\"></span>' + (label || \"Working\"); }\n  else  { btn.disabled = false; if(btn.dataset.was) btn.innerHTML = btn.dataset.was; }\n}\nfunction show(id){\n  [\"stepForm\",\"stepChoice\",\"stepCode\",\"stepHealth\"].forEach(function(s){\n    $(s).hidden = (s !== id);\n  });\n  window.scrollTo({ top: 0, behavior: \"smooth\" });\n}\n\n/* Alert boxes are swallowed inside app previews and blocked by some phone\n   browsers, which makes a failure look like nothing happening at all. Every\n   message goes on the page instead. */\nfunction say(text, kind){\n  var m = $(STAFF ? \"msgS\" : \"msg\");\n  if(!m){ alert(text); return; }\n  m.className = \"banner \" + (kind || \"bad\");\n  m.textContent = text;\n  m.hidden = false;\n  m.scrollIntoView({ behavior: \"smooth\", block: \"nearest\" });\n}\nfunction clearMsg(){ var m = $(\"msg\"); if(m) m.hidden = true; }\n\n\n/* ---------- which screen ------------------------------------------------- */\nvar DEBUG = qs(\"debug\") === \"1\";\nvar STAFF = qs(\"staff\") === \"1\";\n$(\"pub\").hidden   = STAFF || DEBUG;\n$(\"staff\").hidden = !STAFF || DEBUG;\n$(\"dbg\").hidden   = !DEBUG;\n\nif(DEBUG){\n  $(\"dbgPing\").addEventListener(\"click\", function(){\n    LOG = [];\n    log_(LOCAL ? \"route: script tag (local file)\" : \"route: /api on this domain\");\n    once_(\"ping\", {}).then(function(r){\n      log_(r && r.ok ? \"RESULT: the page can reach the script. The fault is not this phone.\"\n                     : \"RESULT: answered, but not ok -> \" + JSON.stringify(r));\n    }).catch(function(e){\n      log_(\"RESULT: could not reach it -> \" + (e && e.message));\n    });\n  });\n}\nif(!FF_GYM_URL) $(\"setupWarn\").hidden = false;\n\n\n/* ---------- the opening --------------------------------------------------\n   Staff never see it: they are checking a code at a counter, not being\n   welcomed. It also ends early on a tap, and it always ends \u2014 if anything in\n   here throws, the form must not stay hidden behind a black screen.\n   ------------------------------------------------------------------------ */\n(function(){\n  var intro = $(\"intro\");\n  if(!intro) return;\n\n  if(STAFF){ intro.hidden = true; return; }\n\n  if(FF_LOGO){\n    var m = $(\"introMark\");\n    if(m){ m.textContent = \"\"; var i = new Image(); i.src = FF_LOGO;\n           i.alt = \"Fitness Fuel 360\"; m.appendChild(i); }\n    var h = document.querySelector(\".hero .mark\");\n    if(h){ h.textContent = \"\"; var i2 = new Image(); i2.src = FF_LOGO; i2.alt = \"\";\n           i2.style.width = \"100%\"; i2.style.height = \"100%\";\n           i2.style.objectFit = \"cover\"; i2.style.borderRadius = \"50%\";\n           h.appendChild(i2); }\n  }\n\n  document.body.classList.add(\"ff-intro\");\n\n  var gone = false;\n  function leave(){\n    if(gone) return;\n    gone = true;\n    intro.classList.add(\"is-leaving\");\n    document.body.classList.remove(\"ff-intro\");\n    setTimeout(function(){ intro.hidden = true; }, 520);\n  }\n\n  var quick = window.matchMedia && window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\n  setTimeout(leave, quick ? 300 : 1500);\n  intro.addEventListener(\"click\", leave);\n  intro.addEventListener(\"touchstart\", leave, { passive: true });\n  setTimeout(leave, 4000);          /* whatever happens, the form appears */\n})();\n\n/* ---------- gym from the QR ---------------------------------------------\n   One QR today, so the gym is typed. When a per-gym QR is printed later it\n   carries ?g=<code> \u2014 the field then fills itself and locks, and the code is\n   stored alongside the name so gym-wise reporting actually groups. Nothing\n   else has to change.\n   ----------------------------------------------------------------------- */\nvar GYMS = {\n  /* \"fitzone\": \"Fit Zone, Kharghar\" */\n};\nvar GYMCODE = (qs(\"g\") || \"\").toLowerCase();\nif(GYMCODE && GYMS[GYMCODE]){\n  $(\"i-gym\").value = GYMS[GYMCODE];\n  $(\"i-gym\").readOnly = true;\n  $(\"gymTag\").textContent = GYMS[GYMCODE];\n  $(\"gymTag\").hidden = false;\n}\n\n/* ---------- form --------------------------------------------------------- */\n$(\"i-mobile\").addEventListener(\"input\", function(){\n  this.value = this.value.replace(/\\D/g, \"\").slice(0, 10);\n});\n$(\"i-dob\").addEventListener(\"change\", function(){\n  var a = ageFrom(this.value);\n  $(\"ageHint\").textContent = a == null ? \"\" : a + \" years old\";\n});\n[\"i-name\",\"i-mobile\",\"i-email\",\"i-gender\",\"i-dob\",\"i-gym\"].forEach(function(id){\n  $(id).addEventListener(\"input\", function(){\n    $(\"f-\" + id.slice(2)).classList.remove(\"bad\");\n  });\n});\n\nfunction readForm(){\n  var v = {\n    name:   $(\"i-name\").value.trim(),\n    mobile: $(\"i-mobile\").value.trim(),\n    email:  $(\"i-email\").value.trim(),\n    gender: $(\"i-gender\").value,\n    dob:    $(\"i-dob\").value,\n    gym:    $(\"i-gym\").value.trim(),\n    gymCode: GYMCODE || \"\"\n  };\n  var bad = [];\n  if(v.name.length < 2)                       bad.push(\"name\");\n  if(!/^[6-9]\\d{9}$/.test(v.mobile))          bad.push(\"mobile\");\n  if(!/^[^@\\s]+@[^@\\s]+\\.[^@\\s]{2,}$/.test(v.email)) bad.push(\"email\");\n  if(!v.gender)                               bad.push(\"gender\");\n  if(ageFrom(v.dob) == null)                  bad.push(\"dob\");\n  if(v.gym.length < 2)                        bad.push(\"gym\");\n\n  [\"name\",\"mobile\",\"email\",\"gender\",\"dob\",\"gym\"].forEach(function(k){\n    $(\"f-\" + k).classList.toggle(\"bad\", bad.indexOf(k) >= 0);\n  });\n  if(bad.length){\n    var el = $(\"f-\" + bad[0]);\n    el.scrollIntoView({ behavior: \"smooth\", block: \"center\" });\n    var inp = el.querySelector(\"input,select\"); if(inp) inp.focus({ preventScroll: true });\n    return null;\n  }\n  v.age = ageFrom(v.dob);\n  return v;\n}\n\nvar FORM = null;\n$(\"btnNext\").addEventListener(\"click\", function(){\n  var v = readForm();\n  if(!v) return;\n  FORM = v;\n  $(\"choiceNote\").textContent = \"Thanks, \" + v.name.split(\" \")[0] + \". Pick one below.\";\n  show(\"stepChoice\");\n});\n$(\"backToForm\").addEventListener(\"click\", function(){ show(\"stepForm\"); });\n$(\"backToChoice\").addEventListener(\"click\", function(){ show(\"stepChoice\"); });\n\n/* ---------- submit ------------------------------------------------------- */\nfunction submit(choice, btn){\n  if(!FF_GYM_URL){\n    say(\"This page is not connected to the sheet yet. Paste the Apps Script URL into FF_GYM_URL.\");\n    return;\n  }\n  clearMsg();\n  var body = {};\n  for(var k in FORM) body[k] = FORM[k];\n  body.choice = choice;\n\n  busy(btn, true, \"Saving\");\n  call(\"submit\", body).then(function(res){\n    busy(btn, false);\n    if(!res || !res.ok){\n      say((res && res.error) ? res.error : \"Could not save. Please try once more.\");\n      return;\n    }\n    clearMsg();\n    if(choice === \"health\"){ show(\"stepHealth\"); return; }\n    $(\"outCode\").textContent = res.code;\n    $(\"outExp\").textContent  = \"Valid till \" + niceDate(res.expiry);\n    $(\"outExp2\").textContent = niceDate(res.expiry);\n    $(\"oldCodeNote\").hidden  = !res.existing;\n    show(\"stepCode\");\n  }).catch(function(err){\n    busy(btn, false);\n    say(\"Could not reach the server. \" + (err && err.message ? err.message : \"\"));\n  });\n}\n$(\"cRedeem\").addEventListener(\"click\", function(){ submit(\"redeem\", this); });\n$(\"cHealth\").addEventListener(\"click\", function(){ submit(\"health\", this); });\n\n$(\"btnCopy\").addEventListener(\"click\", function(){\n  var t = $(\"outCode\").textContent, b = this;\n  var done = function(){ b.textContent = \"Copied\"; setTimeout(function(){ b.textContent = \"Copy code\"; }, 1600); };\n  if(navigator.clipboard && navigator.clipboard.writeText){\n    navigator.clipboard.writeText(t).then(done, function(){});\n  }else{\n    var ta = document.createElement(\"textarea\");\n    ta.value = t; document.body.appendChild(ta); ta.select();\n    try{ document.execCommand(\"copy\"); done(); }catch(e){}\n    document.body.removeChild(ta);\n  }\n});\n\n/* ====================== verification screen ============================== */\nif(STAFF){\n  var FOUND = null;\n\n  var STATUS = {\n    valid:   { tag:\"green\", word:\"Valid\",         line:\"Apply 10% off and mark it used.\" },\n    used:    { tag:\"red\",   word:\"Already used\",  line:\"This code was used before. Do not apply the discount again.\" },\n    expired: { tag:\"amber\", word:\"Expired\",       line:\"The 90 days are over. Do not apply the discount.\" },\n    health:  { tag:\"grey\",  word:\"No code\",       line:\"This person chose health guidance, so no discount code was issued.\" }\n  };\n\n  function render(r){\n    FOUND = r;\n    var box = $(\"vResult\"); box.hidden = false;\n    if(!r){\n      box.innerHTML = '<div class=\"banner bad\" style=\"margin:0\">'\n        + 'Nothing found for that code or number. Check the spelling, or search the mobile number instead.</div>';\n      return;\n    }\n    var s = STATUS[r.status] || STATUS.used;\n    var h = '<div class=\"vhead\">'\n          + '<span class=\"c\">' + esc(r.code || \"\u2014\") + '</span>'\n          + '<span class=\"tag ' + s.tag + '\">' + s.word + '</span></div>'\n          + '<div class=\"banner ' + (r.status === \"valid\" ? \"ok\" : r.status === \"expired\" ? \"warn\" : \"bad\")\n          + '\">' + s.line + '</div>'\n          + '<dl class=\"dl\">'\n          + '<dt>Name</dt><dd>' + esc(r.name) + '</dd>'\n          + '<dt>Mobile</dt><dd>' + esc(r.mobile) + '</dd>'\n          + '<dt>Gym</dt><dd>' + esc(r.gym || \"\u2014\") + '</dd>'\n          + '<dt>Registered</dt><dd>' + niceDate(r.submitted) + '</dd>'\n          + '<dt>Valid till</dt><dd>' + niceDate(r.expiry) + '</dd>';\n    if(r.status === \"used\"){\n      h += '<dt>Used on</dt><dd>' + niceDate(r.usedDate) + '</dd>'\n        +  '<dt>Used at</dt><dd>' + esc(r.usedBy || \"\u2014\") + '</dd>';\n    }\n    h += '</dl>';\n    if(r.status === \"valid\"){\n      h += '<div style=\"margin-top:18px\"><button class=\"btn gold\" id=\"btnUse\">Mark as used</button></div>';\n    }\n    box.innerHTML = h;\n    if(r.status === \"valid\"){\n      $(\"btnUse\").addEventListener(\"click\", markUsed);\n    }\n  }\n\n  function find(){\n    var q = $(\"q\").value.trim();\n    if(!q) return;\n    if(!FF_GYM_URL){ say(\"This page is not connected to the sheet yet.\"); return; }\n    clearMsg();\n    var b = $(\"btnFind\");\n    busy(b, true, \"Searching\");\n    call(\"lookup\", { q: q }).then(function(res){\n      busy(b, false);\n      render(res && res.ok ? res.row : null);\n    }).catch(function(err){\n      busy(b, false);\n      say(\"Could not reach the server. \" + (err && err.message ? err.message : \"\"));\n    });\n  }\n\n  /* Two taps rather than a confirm box: confirm() is blocked in app previews\n     and in some phone browsers, and a blocked box means the code silently\n     never gets marked. */\n  function markUsed(){\n    if(!FOUND) return;\n    var b = $(\"btnUse\");\n    var by = $(\"i-store\").value.trim();\n    if(!by){\n      say(\"Type the store and your name first, so the record shows who applied it.\", \"warn\");\n      $(\"i-store\").focus();\n      return;\n    }\n    if(b.dataset.armed !== \"1\"){\n      b.dataset.armed = \"1\";\n      b.textContent = \"Tap again to confirm \u2014 this cannot be undone\";\n      setTimeout(function(){\n        if(b.dataset.armed === \"1\"){ b.dataset.armed = \"\"; b.textContent = \"Mark as used\"; }\n      }, 6000);\n      return;\n    }\n    b.dataset.armed = \"\";\n    clearMsg();\n    busy(b, true, \"Marking\");\n    call(\"markused\", { code: FOUND.code, by: by }).then(function(res){\n      busy(b, false);\n      if(!res || !res.ok){\n        say((res && res.error) ? res.error : \"Could not mark it. Try again.\");\n        if(res && res.row) render(res.row);\n        return;\n      }\n      say(\"Marked used. \" + FOUND.code + \" will not work again.\", \"ok\");\n      render(res.row);\n    }).catch(function(err){\n      busy(b, false);\n      say(\"Could not reach the server, so nothing was changed. \"\n        + (err && err.message ? err.message : \"\"));\n    });\n  }\n\n  $(\"btnFind\").addEventListener(\"click\", find);\n  $(\"q\").addEventListener(\"keydown\", function(e){ if(e.key === \"Enter\") find(); });\n}\n</script>\n</body>\n</html>\n";

const json_ = (obj, status = 200) => new Response(JSON.stringify(obj), {
  status,
  headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" }
});

export default {
  async fetch(request) {
    const url = new URL(request.url);

    if (url.pathname === "/api" || url.pathname === "/api/") {
      const target = new URL(SCRIPT_URL);
      url.searchParams.forEach((v, k) => {
        if (k !== "key" && k !== "callback") target.searchParams.set(k, v);
      });
      target.searchParams.set("key", SHARED_KEY);

      try {
        const upstream = await fetch(target.toString(), {
          redirect: "follow",
          headers: { "accept": "application/json" }
        });
        const body = await upstream.text();

        /* Apps Script answers with an HTML page when something is wrong at
           its end. Passing that through would land the page back at
           "Unexpected token <", so name it instead. */
        if (body.trim().startsWith("<")) {
          return json_({ ok: false,
            error: "Apps Script returned a page, not data (HTTP " + upstream.status +
                   "). Check the deployment is set to Anyone." }, 502);
        }
        return new Response(body, {
          headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" }
        });
      } catch (err) {
        return json_({ ok: false, error: "Could not reach Apps Script: " + err.message }, 502);
      }
    }

    return new Response(PAGE, {
      headers: {
        "content-type": "text/html; charset=utf-8",
        "cache-control": "no-store, must-revalidate",
        "x-content-type-options": "nosniff"
      }
    });
  }
};
